    { n: 4, drugs: ["atx"], when: "If lisdexamfetamine or methylphenidate cannot be tolerated, or neither helped after separate 6-week trials, having considered other preparations and adequate doses", clause: "1.7.15", src: "NICE NG87 1.7.15" },
    { n: 5, drugs: [], action: "tertiary", when: "No response to one or more stimulants and one non-stimulant: second opinion or tertiary referral. Guanfacine, clonidine and any other medicine only with tertiary advice", clause: "1.7.16–1.7.17", src: "NICE NG87 1.7.16–1.7.17" }
