  { id: "cx_breathless", t: "Breathlessness on exertion compared with peers", ask: "When you exercise, do you get much more out of breath than other people your age?", askYoung: "When your child runs or plays sport, do they get much more out of breath than other children their age?", hist: ["physical_breathless"], action: "cardiology", src: "NICE NG87 1.7.5" },
  { id: "cx_faint", t: "Fainting on exertion or in response to fright or noise", ask: "Have you ever fainted during exercise, or when suddenly frightened or startled by a loud noise?", askYoung: "Has your child ever fainted during exercise, or when suddenly frightened or startled by a loud noise?", hist: ["physical_syncope"], action: "cardiology", src: "NICE NG87 1.7.5" },
  { id: "cx_palp", t: "Palpitations that are rapid, regular and start and stop suddenly", ask: "Have you had spells of a very fast, regular heartbeat that starts and stops suddenly? (Occasional skipped beats or 'bumps' are usually harmless and need no tests.)", askYoung: "Has your child had spells of a very fast, regular heartbeat that starts and stops suddenly? (Occasional skipped beats are usually harmless.)", hist: ["physical_palpitations"], action: "cardiology", src: "NICE NG87 1.7.5" },
  { id: "cx_chestpain", t: "Chest pain suggesting a heart cause", ask: "Have you had chest pain, especially when exercising?", askYoung: "Has your child complained of chest pain, especially when exercising?", hist: ["physical_chestpain"], action: "cardiology", src: "NICE NG87 1.7.5" },
  { id: "cx_hf", t: "Signs of heart failure", ask: "On examination: are there signs of heart failure?", action: "cardiology", src: "NICE NG87 1.7.5" },
  { id: "cx_murmur", t: "A murmur heard on heart examination", ask: "On examination: is there a heart murmur?", action: "cardiology", src: "NICE NG87 1.7.5" },
  { id: "cx_htn", ages: "adult", t: "Blood pressure in the hypertensive range for adults", ask: "Is hypertension confirmed: clinic BP 140/90 or higher, with an ambulatory or home average of 135/85 or higher? (The blood pressure check above works this out from the readings.)", action: "cardiology", src: "NICE NG87 1.7.5; NICE NG136 1.2.3–1.2.8" },
  { id: "cx_med", t: "Takes a medicine for another condition that may increase cardiac risk", ask: "Do you take any medicine that can affect the heart or its rhythm (for example some antipsychotics or antidepressants)?", askYoung: "Does your child take any medicine that can affect the heart or its rhythm?", hist: ["meds_cardiac"], action: "ecg", src: "NICE NG87 1.7.4" },
  { id: "cx_known", t: "A known heart condition: heart failure, cardiomyopathy, a heart rhythm problem or a heart murmur", ask: "Have you been told you have a heart condition, such as heart failure, cardiomyopathy, a heart rhythm problem or a heart murmur?", askYoung: "Has your child been told they have a heart condition, such as a heart rhythm problem or a heart murmur?", hist: ["physical_heartother"], action: "cardiology", src: "NICE NG87 1.7.5 (signs of heart failure, a murmur); clinical practice (other known heart conditions: cardiology opinion before starting)" }
