    { id: "sp_when", t: "Ask for shared care after titration, once the dose is stable.", src: "NICE NG87 1.7.29" },
    { id: "sp_timing", t: "Transfer usually happens after at least 12 weeks, once the dose is optimised and results have been satisfactory for at least 4 weeks.", src: "NHS England national shared care protocol: atomoxetine in adults (v1, July 2022); local protocols vary" },
    { id: "sp_reply", t: "Primary care replies within about 14 days. Shared care is voluntary: keep prescribing, and prescribe enough to cover any delay, until the GP agrees.", src: "NHS England national shared care protocol (2022); local protocols vary" }
